class DefaultAzureCredential {
  let @tenant_id: String
  let @client_id: String
  let @client_secret: String
  let @access_token: Option[String]

  fn static new > DefaultAzureCredential {
    let tenant_id = match env.get("AZURE_TENANT_ID") {
      case Some(v) > v
      case None > ""
    }
    let client_id = match env.get("AZURE_CLIENT_ID") {
      case Some(v) > v
      case None > ""
    }
    let client_secret = match env.get("AZURE_CLIENT_SECRET") {
      case Some(v) > v
      case None > ""
    }
    DefaultAzureCredential {
      @tenant_id = tenant_id,
      @client_id = client_id,
      @client_secret = client_secret,
      @access_token = Option.None,
    }
  }

  fn mut get_token(resource: String) > String {
    match @access_token {
      case Some(ref t) > return t.clone
      case None > {}
    }

    let token_url = ""
    let body = "grant_type=client_credentials&client_id=${@client_id}&client_secret=${@client_secret}&scope=${resource}/.default"

    let client = Client.new
    let headers = Headers.new
    headers.set("ContentType", "application/xwwwformurlencoded")
    let request = Request.new(Method.Post, token_url, headers, body.to_byte_array)
    let response = match client.send(request) {
      case Ok(r) > r
      case Error(_) > {
        @access_token = Option.Some("")
        return ""
      }
    }

    let response_body = response.body_to_string
    let parsed = match Json.parse(response_body) {
      case Ok(v) > v
      case Error(_) > {
        @access_token = Option.Some("")
        return ""
      }
    }

    let token = match parsed {
      case Json.Object(ref obj) > {
        match obj.get("access_token") {
          case Some(Json.String(ref s)) > s.clone
          case _ > ""
        }
      }
      case _ > ""
    }

    @access_token = Option.Some(token.clone)
    token
  }
}

