    body_obj.set("agent_reference", Json.Object(agent_ref))

    let body_string = Json.Object(body_obj).to_string

    let url = "${@base_url}/openai/responses?apiversion=20250101"

    let client = Client.new
    let headers = Headers.new
    headers.set("ContentType", "application/json")
    headers.set("Authorization", "Bearer ${@token}")

    let request = Request.new(Method.Post, url, headers, body_string.to_byte_array)
