    let parsed = match Json.parse(response_body) {
      case Ok(v) > v
      case Error(_) > return ResponseOutput.new("")
    }

    let output_text = match parsed {
      case Json.Object(ref obj) > {
        match obj.get("output") {
          case Some(Json.Array(ref arr)) > {
            let mut text = ""
            let mut i = 0
            while i < arr.length {
              match arr.get(i) {
                case Some(Json.Object(ref item)) > {
                  match item.get("content") {
                    case Some(Json.Array(ref content_arr)) > {
                      let mut j = 0
                      while j < content_arr.length {
                        match content_arr.get(j) {
                          case Some(Json.Object(ref content_item)) > {
