  let @expires_on: Int

  fn static obtain(resource: String) -> AzureIdentityToken {
    let client = Client.new
    let metadata_url = "http://169.254.169.254/metadata/identity/oauth2/token?api-version=2018-02-01&resource={resource}"
    let request = Request.new(Method.Get, metadata_url)
